// ---- data from the queue-service (through the api-gateway)
function useEstablishments() {
 const [list,setList]=useState<Est[]|null>(null);const [error,setError]=useState('');
 useEffect(()=>{api.establishments().then(setList).catch(e=>setError(e.message))},[]);
 return {list,error};
}
function useMyTickets(pollMs=0) {
 const [tickets,setTickets]=useState<Tk[]|null>(null);const [offline,setOffline]=useState(false);
 const refresh=()=>api.myTickets().then(l=>{setTickets(l);setOffline(false)}).catch(()=>setOffline(true));
 useEffect(()=>{refresh();if(!pollMs)return;const t=setInterval(refresh,pollMs);return()=>clearInterval(t)},[pollMs]); // eslint-disable-line react-hooks/exhaustive-deps
 return {tickets,offline,refresh};
}
function useMyAppointments() {
 const [appointments,setAppointments]=useState<Appt[]|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);
 const refresh=()=>{setLoading(true);return api.appointments().then(items=>{setAppointments(items);setError('')}).catch(e=>setError(errorText(e))).finally(()=>setLoading(false))};
 useEffect(()=>{void refresh()},[]);
 return {appointments,error,loading,refresh};
}
const localDateValue=(date:Date)=>{const year=date.getFullYear();const month=String(date.getMonth()+1).padStart(2,'0');const day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`};
const appointmentDate=(value:string)=>new Date(value).toLocaleString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const errorText=(e:unknown)=>e instanceof ApiError&&e.status===409?'Vous avez déjà un ticket dans cette file.':e instanceof ApiError&&e.status===403?"Votre compte n'a pas le rôle agent.":e instanceof Error?e.message:'Erreur inattendue';

function Button({children,onClick,kind='dark',className='',type='button'}:{children:React.ReactNode;onClick?:()=>void;kind?:'dark'|'light'|'teal'|'plain';className?:string;type?:'button'|'submit'}) {
  return <button type={type} onClick={onClick} className={`${kind==='dark'?'btn-dark':kind==='light'?'btn-light':kind==='teal'?'btn-teal':'plain-button'} ${className}`} data-testid="button-action">{children}</button>;
}
function Brand({dark=false}:{dark?:boolean}) { return <Link href="/" className="brand" data-testid="link-home"><span className="brand-mark"><i/><i/><i/><i/></span><span style={{fontWeight:800,letterSpacing:'-.06em',fontSize:22,color:dark?'#f6faf8':'#122235'}}>tiko<span style={{color:'#1fa38a'}}>.</span></span></Link> }
function Pill({children,tone='green'}:{children:React.ReactNode;tone?:'green'|'amber'|'red'|'gray'|'white'}) { const colors={green:['#e6f6ee','#258466'],amber:['#fff2dc','#ad6c12'],red:['#fff0ee','#cb5147'],gray:['#edf1ef','#6c7973'],white:['rgba(255,255,255,.12)','#dce8e2']};return <span className="status-pill" style={{background:colors[tone][0],color:colors[tone][1]}}>{children}</span> }
function Hub() {
 const [open,setOpen]=useState(false);
 return <><button onClick={()=>setOpen(true)} className="hub-trigger" data-testid="button-prototype-hub"><span className="hub-dot"/>Plan du prototype<ArrowUpRight size={15}/></button>{open&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setOpen(false)}}><div className="hub-modal glass fade-up" role="dialog" aria-modal="true" aria-labelledby="hub-heading"><button className="modal-x" aria-label="Fermer" onClick={()=>setOpen(false)}><X size={18}/></button><div className="label">Navigation rapide</div><h2 id="hub-heading">Plan du prototype</h2><p className="muted">Parcourez les trois espaces Tiko et les décisions en attente.</p><div className="hub-list">{[['Site client','/login','Espace public · tickets et rendez-vous'],['Back-office établissement','/tenant','Équipe et administration'],['Console fournisseur','/provider','Gestion multi-organisations'],['Décisions ouvertes','/decisions','Hypothèses à valider']].map(([name,href,desc])=><Link key={href} href={href} onClick={()=>setOpen(false)} className="hub-row" data-testid={`link-hub-${href.slice(1)}`}><span><b>{name}</b><small>{desc}</small></span><ArrowRight size={17}/></Link>)}</div></div></div>}</>
}
function AvatarStack() { return <div className="avatar-stack"><span>SB</span><span>MK</span><span>YA</span><i>+2k</i></div> }
