 const submitOrg=()=>{if(!newOrg.name||!newOrg.admin||!newOrg.email){setError('Complétez tous les champs obligatoires.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(newOrg.email)){setError('Adresse e-mail invalide');return}setList(l=>[...l,{name:newOrg.name,kind:newOrg.type,plan:newOrg.plan,status:'Actif'}]);setCreated(true);setSelected(newOrg.name);setPage('Organisations');setError('')};
